import{_ as e,c as l,o as r,a4 as n}from"./chunks/framework.C-Sv_Sou.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"md-interview/distribution.md","filePath":"md-interview/distribution.md","lastUpdated":1783862120000}'),s={name:"md-interview/distribution.md"};function o(g,t,d,a,i,f){return r(),l("div",null,[...t[0]||(t[0]=[n('<h2 id="_2026-年前端面试" tabindex="-1">2026 年前端面试 <a class="header-anchor" href="#_2026-年前端面试" aria-label="Permalink to &quot;2026 年前端面试&quot;">​</a></h2><h3 id="内容分布" tabindex="-1">内容分布 <a class="header-anchor" href="#内容分布" aria-label="Permalink to &quot;内容分布&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">考察模块</th><th style="text-align:left;">预估占比</th><th style="text-align:left;">核心考察点（高频 &amp; 重点）</th><th style="text-align:left;">考察形式与能力要求</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>项目经历与工程化</strong></td><td style="text-align:left;"><strong>约30%</strong></td><td style="text-align:left;">- <strong>复杂场景实现</strong>：虚拟列表（尤其是动态高度）、复杂表单状态管理、微前端架构设计与通信。<br>- <strong>性能优化</strong>：首屏与构建优化（如靠前的Chunk、Tree Shaking）、运行时性能（内存泄漏、长任务）。<br>- <strong>工程化基建</strong>：自定义脚手架、CICD流水线配置、Monorepo管理、Babel插件。</td><td style="text-align:left;">深挖细节，重点考察技术决策过程和量化成果（例如“首屏加载时间减少了X%”）。</td></tr><tr><td style="text-align:left;"><strong>前端基础与原理</strong></td><td style="text-align:left;"><strong>约25%</strong></td><td style="text-align:left;">- <strong>JavaScript</strong>：<code>this</code>、原型链、异步（Event Loop、Promise）、垃圾回收。<br>- <strong>CSS</strong>：布局（Flex/Grid）、响应式、层叠上下文、新特性（容器查询）。<br>- <strong>浏览器与网络</strong>：渲染原理（重排/重绘）、HTTP缓存与协议、跨域解决方案。<br>- <strong>框架（以React为主）</strong>：Fiber架构与时间切片、Hooks原理（如<code>useEffect</code>的依赖收集）、合成事件。</td><td style="text-align:left;">死记硬背“八股文”回报降低，更侧重考察底层原理在实际问题中的应用与分析。</td></tr><tr><td style="text-align:left;"><strong>AI工程化能力</strong></td><td style="text-align:left;"><strong>约20%</strong></td><td style="text-align:left;">- <strong>AI辅助开发</strong>：如何设计Prompt、如何保证AI生成代码的安全与质量。<br>- <strong>AI应用集成</strong>：处理大模型流式响应（解析不完全的JSON块）、设计Agent工作流（如RAG检索增强）。<br>- <strong>AI工具链</strong>：VSCode插件（GitHub Copilot、Cursor）、AI Code Review。</td><td style="text-align:left;">面试官想了解的是你<strong>如何利用AI提效</strong>，而非简单的API调用。重在展示工程化应用与最佳实践。</td></tr><tr><td style="text-align:left;"><strong>算法与手写代码</strong></td><td style="text-align:left;"><strong>约15%</strong></td><td style="text-align:left;">- <strong>手写核心功能</strong>：<code>Promise.all</code>、带并发限制的调度器、深拷贝、数组拍平去重。<br>- <strong>数据结构与算法</strong>：常见数据结构的应用（数组、字符串）、DFS/BFS、简单的动态规划。</td><td style="text-align:left;">主要出现在在线笔试或第一轮面试，注重代码逻辑清晰、边界条件完整、时间/空间复杂度分析。</td></tr><tr><td style="text-align:left;"><strong>系统设计</strong></td><td style="text-align:left;"><strong>约10%</strong></td><td style="text-align:left;">- <strong>前端架构设计</strong>：设计前端监控SDK、设计高可用的支付页面、设计实时协作编辑器。<br>- <strong>全栈/接口设计</strong>：设计BFF层、设计API接口、设计Webhook系统。</td><td style="text-align:left;">常见于中大型或外企面试，考察你的抽象能力、架构思维和数据流设计能力。</td></tr></tbody></table><hr><h3 id="按面试流程的常见环节分布" tabindex="-1">按面试流程的常见环节分布 <a class="header-anchor" href="#按面试流程的常见环节分布" aria-label="Permalink to &quot;按面试流程的常见环节分布&quot;">​</a></h3><p>除了按知识模块划分，你还可以按面试流程来准备，这样更有针对性：</p><table tabindex="0"><thead><tr><th style="text-align:left;">面试环节</th><th style="text-align:left;">常见时长</th><th style="text-align:left;">考察重点</th><th style="text-align:left;">淘汰率</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>在线笔试 / 初筛</strong></td><td style="text-align:left;">60-90分钟</td><td style="text-align:left;">算法与数据结构（LeetCode中等难度）、JavaScript基础、CSS布局、少量React原理。</td><td style="text-align:left;"><strong>较高</strong>，主要用于快速筛选。</td></tr><tr><td style="text-align:left;"><strong>第一轮：技术面</strong></td><td style="text-align:left;">45-60分钟</td><td style="text-align:left;">前端基础与原理（深度提问）、项目经历（开始引入场景题）、手写代码（核心功能）。</td><td style="text-align:left;">中等，基础不牢容易淘汰。</td></tr><tr><td style="text-align:left;"><strong>第二轮：深入技术/项目面</strong></td><td style="text-align:left;">60-90分钟</td><td style="text-align:left;"><strong>项目经历（核心）</strong>：深度追问技术选型、难点攻克、量化成果。<br><strong>工程化与性能</strong>：CI/CD、打包优化、监控。<br><strong>AI工程化</strong>：AI集成实践。</td><td style="text-align:left;"><strong>最高</strong>，这是区分候选人的关键轮次。</td></tr><tr><td style="text-align:left;"><strong>第三轮：交叉/架构面</strong></td><td style="text-align:left;">45-60分钟</td><td style="text-align:left;"><strong>系统设计</strong>：考察架构抽象能力。<br><strong>软技能</strong>：跨团队协作、技术规划、学习能力。</td><td style="text-align:left;">中等，看重潜力和沟通。</td></tr><tr><td style="text-align:left;"><strong>HR面</strong></td><td style="text-align:left;">30分钟</td><td style="text-align:left;">价值观匹配、稳定性、职业规划、薪资沟通。</td><td style="text-align:left;">较低，主要看软素质。</td></tr></tbody></table><hr><h3 id="给你的核心策略建议" tabindex="-1">给你的核心策略建议 <a class="header-anchor" href="#给你的核心策略建议" aria-label="Permalink to &quot;给你的核心策略建议&quot;">​</a></h3><ol><li><p><strong>项目经历是“定生死”的关键</strong>：</p><ul><li>准备好1-2个最能体现你技术深度的项目，按照 <strong>STAR原则</strong>（背景、任务、行动、结果）组织语言。</li><li>对每个技术决策都要能回答“为什么选A不选B？”。</li><li><strong>复盘量化成果</strong>：比如“优化后，LCP从2.5s降到1.2s”。</li></ul></li><li><p><strong>重视AI工程化，而不只是AI调用</strong>：</p><ul><li>在简历和项目中，体现你如何将AI融入工作流。例如：“设计并实现了基于AI的代码审查助手，将重复问题检出率提升30%”。</li><li>尝试了解<code>LangChain</code>、<code>Vercel AI SDK</code>等前沿工具，能说出它们在处理流式响应上的优势。</li></ul></li><li><p><strong>算法保持手感，但不求偏难怪</strong>：</p><ul><li>重点攻克 <strong>数组、字符串、哈希表、递归/DFS/BFS、简单的DP</strong>。</li><li>手写Promise周边和深拷贝等，要能<strong>一次性写出健壮的代码</strong>。</li></ul></li></ol>',10)])])}const h=e(s,[["render",o]]);export{y as __pageData,h as default};
